// Pre-pass that normalises the source before edge-lexer sees it:
//   1. Extract content of raw-text elements (<style>, <script>, <pre>,
//      <textarea>) and stash it in a side table, replacing the body with a
//      sentinel that round-trips through the lexer / HTML parser. The
//      printer pulls the original content back from the side table.
//   2. Split inline Edge tag constructs onto their own lines so the lexer
//      accepts them (it throws on "leftover" content after a seekable tag).

const RAW_TEXT_RE = /<(script|style|pre|textarea)(\s[^>]*)?>([\s\S]*?)<\/\1\s*>/gi

// Match HTML comments including downlevel-conditional comments
// (`<!--[if IE]>…<![endif]-->`). We scan for these so raw-text extraction
// doesn't reach inside them.
const HTML_COMMENT_RE = /<!--[\s\S]*?-->/g

// XML processing instructions: `<?xml … ?>` etc. angular-html-parser
// silently rewrites these as comments, which breaks round-tripping.
const PI_RE = /<\?[\s\S]*?\?>/g

// `@raw … @end` blocks. Paren-less opener, body is verbatim Edge-source
// (no mustache or tag interpretation), closed by the next `@end` on its
// own line. Edge's runtime stops scanning at the first `@end`, so we do
// the same. The capture groups are:
//   1: leading line break (or empty if file starts with `@raw`)
//   2: indent of the @raw line
//   3: opener swallow flag (`~` or empty)
//   4: body content (everything up to but not including the closing line)
//   5: closer swallow flag
const RAW_BLOCK_RE = /(^|\n)([ \t]*)@raw(~?)[ \t]*\r?\n([\s\S]*?)\r?\n[ \t]*@end(~?)/g

const IDENT_START = /[A-Za-z_$]/
const IDENT_CONT = /[\w$]/

export function preprocess(source) {
  const rawTexts = new Map()
  const rawBlocks = new Map()
  let rawId = 0
  let blockId = 0
  // Stage A: extract `@raw … @end` blocks first, before any other
  // pass touches them. Their bodies are verbatim Edge source — must
  // not pass through edge-lexer or the HTML parser.
  let stageRaw = source.replace(
    RAW_BLOCK_RE,
    (_full, lead, indent, openSwallow, body, closeSwallow) => {
      const id = blockId++
      const baseline = indent.length
      const dedented = dedentByBaseline(body, baseline)
      rawBlocks.set(id, {
        body: dedented,
        openSwallow: openSwallow === '~',
        closeSwallow: closeSwallow === '~',
      })
      return `${lead}${indent}<edge-rawblock data-edge-id="${id}"></edge-rawblock>`
    }
  )
  // Replace XML processing instructions with HTML comments carrying a
  // sentinel marker. The HTML parser handles HTML comments cleanly, and
  // the printer recognises the sentinel to emit the original PI back.
  let stage0 = stageRaw.replace(PI_RE, (full) => {
    const id = rawId++
    rawTexts.set(id, full)
    return `<!--__EDGE_PI_${id}__-->`
  })
  // Find HTML comment ranges so we can skip raw-text matches that sit
  // inside conditional comments (e.g. `<!--[if IE]><script>…</script><![endif]-->`).
  const commentRanges = []
  HTML_COMMENT_RE.lastIndex = 0
  let cm
  while ((cm = HTML_COMMENT_RE.exec(stage0)) !== null) {
    commentRanges.push([cm.index, cm.index + cm[0].length])
  }
  const insideComment = (pos) => {
    for (const [s, e] of commentRanges) if (pos >= s && pos < e) return true
    return false
  }
  let stage1 = stage0.replace(RAW_TEXT_RE, (full, tag, attrs, body, offset) => {
    if (insideComment(offset)) return full
    const id = rawId++
    rawTexts.set(id, body)
    return `<${tag}${attrs ?? ''}>__EDGE_RAW_${id}__</${tag}>`
  })
  // Alpine.js / Livewire attributes look like `@click="..."`,
  // `@click.prevent="..."`, or `@toggle-mobile-nav.window="..."`. When they
  // wrap onto a new line of a multi-line HTML opening tag they sit at
  // column 0 (after indentation) and edge-lexer mistakes them for Edge
  // tags missing parens. Replace the leading `@` with a sentinel before
  // the lexer sees it; the splice phase converts the sentinel back.
  const stageAlpine = maskAlpineAttributes(stage1)
  const stage2 = splitInlineTags(stageAlpine)
  // edge-lexer's paren scanner is not string-aware: `@if(user.can('view)'))`
  // closes early at the `)` inside the string. Replace multi-line tag args
  // with a placeholder so the lexer sees `@tag(__EDGE_TAGARG_N__)`; we
  // substitute the real args back during AST construction.
  const { source: stage3, tagArgs } = extractMultilineTagArgs(stage2)
  return { source: stage3, rawTexts, rawBlocks, tagArgs }
}

// Strip `baseline` characters of leading whitespace from each non-blank
// line, so the body's indent becomes relative to the `@raw` opener. The
// printer re-adds the host indent at emit time.
function dedentByBaseline(text, baseline) {
  if (baseline === 0) return text
  return text
    .split('\n')
    .map((line) => {
      const ws = line.match(/^[ \t]*/)[0]
      return line.slice(Math.min(ws.length, baseline))
    })
    .join('\n')
}

// An Alpine-style attribute name: identifier with optional hyphenated
// continuation, plus optional `.modifier` segments, immediately followed
// by `=` (and a quote). Only matched at line start (after whitespace) so
// we don't touch `@` characters in JS expressions.
const ALPINE_ATTR_RE =
  /(^|\n)([ \t]*)@([A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z][A-Za-z0-9_-]*)*)\s*=\s*(["'])/g

function maskAlpineAttributes(text) {
  return text.replace(
    ALPINE_ATTR_RE,
    (_m, lead, ws, name, quote) => `${lead}${ws}__edge_alpine__${name}=${quote}`
  )
}

function extractMultilineTagArgs(text) {
  const tagArgs = new Map()
  let nextId = 0
  let out = ''
  let i = 0
  while (i < text.length) {
    if (text[i] === '@' && (i === 0 || text[i - 1] !== '@')) {
      const tag = readEdgeTagDetailed(text, i)
      if (tag && tag.argsStart !== -1) {
        const argText = text.slice(tag.argsStart + 1, tag.argsEnd)
        if (argText.includes('\n')) {
          const id = nextId++
          tagArgs.set(id, argText)
          out += text.slice(i, tag.argsStart + 1)
          out += `__EDGE_TAGARG_${id}__`
          out += text.slice(tag.argsEnd, tag.end)
          i = tag.end
          continue
        }
      }
    }
    out += text[i]
    i += 1
  }
  return { source: out, tagArgs }
}

function readEdgeTagDetailed(text, index) {
  if (text[index] !== '@') return null
  let cursor = index + 1
  if (text[cursor] === '!') cursor += 1
  const first = readIdentifier(text, cursor)
  if (!first) return null
  cursor = first.end
  let name = first.value
  while (text[cursor] === '.') {
    const part = readIdentifier(text, cursor + 1)
    if (!part) return null
    name += `.${part.value}`
    cursor = part.end
  }
  let argsStart = -1
  let argsEnd = -1
  if (text[cursor] === '(') {
    argsStart = cursor
    const close = findMatchingParen(text, cursor)
    if (close === -1) return null
    argsEnd = close
    cursor = close + 1
  } else if (name !== 'end' && name !== 'else' && !/^end[A-Za-z_]/.test(name)) {
    return null
  }
  if (text[cursor] === '~') cursor += 1
  return { name, end: cursor, argsStart, argsEnd }
}

// Find every Edge tag (`@name(args)`, `@!name(args)`, `@end`, `@endNAME`,
// optional trailing `~`) and ensure it sits on its own line.
function splitInlineTags(text) {
  let out = ''
  let i = 0
  while (i < text.length) {
    if (text[i] === '@' && (i === 0 || text[i - 1] !== '@')) {
      const tag = readEdgeTag(text, i)
      if (tag) {
        // Leading content on the same line?
        const lineStart = text.lastIndexOf('\n', i - 1) + 1
        const leading = text.slice(lineStart, i)
        if (leading.trim() !== '' && !out.endsWith('\n')) {
          out += '\n'
        }
        out += text.slice(i, tag.end)
        i = tag.end
        // Trailing content on the same line?
        const nextNl = text.indexOf('\n', i)
        const endOfLine = nextNl === -1 ? text.length : nextNl
        const trailing = text.slice(i, endOfLine)
        if (trailing.trim() !== '') {
          out += '\n'
        }
        continue
      }
    }
    out += text[i]
    i += 1
  }
  return out
}

function readIdentifier(text, index) {
  if (!IDENT_START.test(text[index] ?? '')) return null
  let end = index + 1
  while (end < text.length && IDENT_CONT.test(text[end])) end += 1
  return { value: text.slice(index, end), end }
}

function readEdgeTag(text, index) {
  if (text[index] !== '@') return null
  let cursor = index + 1
  if (text[cursor] === '!') cursor += 1
  const first = readIdentifier(text, cursor)
  if (!first) return null
  cursor = first.end
  let name = first.value
  while (text[cursor] === '.') {
    const part = readIdentifier(text, cursor + 1)
    if (!part) return null
    name += `.${part.value}`
    cursor = part.end
  }
  if (text[cursor] === '(') {
    const close = findMatchingParen(text, cursor)
    if (close === -1) return null
    cursor = close + 1
  } else if (name !== 'end' && name !== 'else' && !/^end[A-Za-z_]/.test(name)) {
    // Bare `@name` without parens (and not @end / @else / @endX) isn't an
    // Edge tag — typically a CSS at-rule or stray @.
    return null
  }
  if (text[cursor] === '~') cursor += 1
  // Tag must be followed by whitespace, end-of-text, `<`, or `@`.
  const next = text[cursor]
  if (next !== undefined && !/[\s<@]/.test(next)) return null
  return { name, end: cursor }
}

function findMatchingParen(text, start) {
  if (text[start] !== '(') return -1
  let depth = 0
  let quote = null
  let escaped = false
  const tplStack = []
  for (let i = start; i < text.length; i += 1) {
    const ch = text[i]
    if (quote) {
      if (escaped) {
        escaped = false
        continue
      }
      if (ch === '\\') {
        escaped = true
        continue
      }
      if (quote === '`' && ch === '$' && text[i + 1] === '{') {
        tplStack.push(0)
        quote = null
        i += 1
        continue
      }
      if (ch === quote) quote = null
      continue
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      quote = ch
      continue
    }
    if (tplStack.length > 0) {
      if (ch === '{') {
        tplStack[tplStack.length - 1] += 1
        continue
      }
      if (ch === '}') {
        if (tplStack[tplStack.length - 1] === 0) {
          tplStack.pop()
          quote = '`'
          continue
        }
        tplStack[tplStack.length - 1] -= 1
        continue
      }
    }
    if (ch === '(') {
      depth += 1
      continue
    }
    if (ch === ')') {
      depth -= 1
      if (depth === 0) return i
    }
  }
  return -1
}
